#define PI 3.14159
#define TWO_PI (2.0*PI)

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Centered screen coords
    vec2 st = fragCoord/iResolution.y * 2.0;
    st.y -= 1.0;
    st.x -= iResolution.x/iResolution.y;

    // Center lower
    const float groundLevel = -0.4;
    st.y -= groundLevel;

    st.x -= 0.15;

    // Save unrotated
    vec2 skySt = st;

    // Rotate
    float a = 1.2;
    st *= mat2(sin(a), cos(a), -cos(a), sin(a));


    float acualTime = mod(iTime, 20.0) * 0.7;


    const float layerThickness = 0.05;

    float rollTime = acualTime + 0.45;
    float nLayersAtBottom = floor(rollTime) + smoothstep(0.9, 1.0, fract(rollTime));
    float radiusAtBottom = layerThickness * nLayersAtBottom;

    vec2 ballCenter = vec2(0.0, radiusAtBottom - layerThickness);

    vec2 stBall = st - ballCenter;
    float angle = atan(stBall.x, stBall.y);
    float nLayers = floor(angle / TWO_PI + acualTime);

    float radius = layerThickness * nLayers;

    vec3 color = vec3(0.0);

    // Sky
    color += vec3(0.1, 0.15, 0.3) * (1.8 - skySt.y);
    color = mix(color, vec3(0.35, 0.45, 0.45), max(0.0, 1.5 - skySt.y));
    color = mix(color, vec3(0.65, 0.65, 0.55), max(0.0, 0.0 - skySt.y));


    // Ball
    float d = distance(st, ballCenter);
    float d1 = floor(d);
    float ballColor = (1.0 - fract(d / layerThickness) * 0.07);
    color = mix(color, vec3(ballColor), step(d, radius));

    // Ground
    // its moving, proportional to radius
    // Its too hard to simulate acceleration in steps (im not a real engineer, see)
    // So assume constant acceleration
    float acceleration = PI * layerThickness;
    acualTime = max(0.0, acualTime - 0.3);
    float xPos = acceleration * acualTime * acualTime;
    vec2 groundSt = st;
    groundSt.x -= xPos;
    float groundColor = 1.0 + st.y / layerThickness * 0.07;
    float tickMarks = step(fract(groundSt.x * 3.0), 0.05) * step(st.y, -0.1);
    color = mix(color, mix(vec3(groundColor), vec3(0.0, 0.0, 0.0), tickMarks), step(st.y + step(0.0, st.x) * layerThickness, 0.0));

    // Output to screen
    fragColor.xyz = vec3(color);
}
